public interface UserRepository extends JpaRepository<User, Long> {
    // Find user by exact email
    Optional<User> findByEmail(String email);

    // Find users whose name contains a substring (ignoring case)
    List<User> findByNameContainingIgnoreCase(String name);

    // Count users with a given email domain (using JPQL in method name? not possible, but we can combine)
    // For complex conditions, use @Query
}

public interface UserRepository extends JpaRepository<User, Long> {

    @Query("SELECT u FROM User u WHERE u.email LIKE %:domain")
    List<User> findByEmailDomain(@Param("domain") String domain);

    // Native SQL (if you must)
    @Query(value = "SELECT * FROM users WHERE name = ?1", nativeQuery = true)
    User findByNameNative(String name);
}
